 */\n\n/* === 基础色变量 (Raw Colors) === */\n/* 报纸主题的基础色定义 */\n:root {\n  /* 核心强调色 */\n  --rust: #8b4513; /* 锈红棕色 - 主强调色 */\n  --rust-light: #a0522d; /* 浅锈色 */\n  --rust-faded: #6b3410; /* 褪色锈色 */\n\n  /* 纸张色系 */\n  --paper-yellow: #d4c5a0; /* 泛黄纸张主色 */\n  --paper-light: #e0d5b8; /* 浅纸张色 */\n  --paper-dark: #b8a880; /* 深纸张色 */\n\n  /* 墨水色系 */\n  --ink-black: #2a2420; /* 墨黑 */\n  --ink-faded: #4a4035; /* 褪色墨 */\n  --ink-light: #6b5f50; /* 浅墨色 */\n\n  /* 装饰色 */\n  --stain: #c4a265; /* 污渍/金色装饰 */\n  --crease: #bfb08a; /* 折痕色 */\n\n  /* 功能色 */\n  --vn-success: #5a7a4a; /* 成功/正向反馈 */\n  --vn-danger: #8b2500; /* 危险/错误提示 */\n\n  /* 主题变量：引用基础色作为默认值 */\n  /* 背景与文字 */\n  --theme-bg: #2a2420;\n  --theme-fg: #d4c5a0;\n  --theme-muted: #8b7d6b;\n\n  /* 强调色 */\n  --theme-accent: var(--rust);\n  --theme-accent-soft: var(--rust-light);\n\n  /* 线条与边框 */\n  --theme-line-color: rgba(90, 79, 64, 0.4);\n  --theme-surface-border: rgba(90, 79, 64, 0.55);\n  --theme-surface-soft: rgba(212, 197, 160, 0.05);\n\n  /* 文本颜色 */\n  --theme-text-main: rgba(212, 197, 160, 0.92);\n  --theme-text-soft: rgba(212, 197, 160, 0.7);\n  --theme-text-muted: rgba(139, 125, 107, 0.8);\n  --theme-text-faint: rgba(139, 125, 107, 0.5);\n  --theme-text-inverse: rgba(42, 36, 32, 0.9);\n  --theme-user-text: #5c8a9c;\n  --theme-dialogue-name-color: var(--rust);\n\n  /* 字体 */\n  --theme-font-body: 'Noto Serif SC', 'Noto Serif', Georgia, serif;\n  --theme-font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;\n\n  /* 兼容变量：旧代码兼容层 */\n  /* 注意：这些变量引用 theme-* 系列，确保双向同步 */\n  --vn-bg: var(--theme-bg);\n  --vn-fg: var(--theme-fg);\n  --vn-muted: var(--theme-muted);\n  --vn-border: rgba(90, 79, 64, 0.55);\n  --vn-panel-bg: rgba(51, 44, 38, 0.96);\n  --vn-dialogue-bg: rgba(42, 36, 32, 0.92);\n  --vn-choice-bg: rgba(58, 51, 44, 0.95);\n  --vn-choice-hover: rgba(139, 69, 19, 0.3);\n  --vn-choice-selected: rgba(139, 69, 19, 0.5);\n  --vn-toast-bg: #d4c5a0;\n  --vn-toast-text: #2a2420;\n\n  /* === 组件层变量 === */\n\n  /* 对话框 */\n  --theme-dialogue-bg: var(--vn-dialogue-bg);\n  --theme-dialogue-border: var(--vn-border);\n  --theme-dialogue-radius: 0px;\n  --theme-dialogue-shadow: inset 0 0 0.5rem rgba(42, 36, 32, 0.3), 0 0.25rem 0.75rem rgba(0, 0, 0, 0.4);\n  --theme-dialogue-text-color: var(--theme-text-main);\n\n  /* 对话框文本字号（关键变量：用 clamp 防\"过小消失\"，用户可直接重写为绝对值） */\n  --theme-dialogue-text-font-size: clamp(0.9rem, 1.6vw, 1.1rem);\n  --theme-dialogue-text-line-height: 1.75;\n  --theme-dialogue-text-letter-spacing: 0.02em;\n\n  /* 对话框文本 padding（用 rem 避免依赖字号缩放） */\n  --theme-dialogue-text-padding-top: 1.5rem;\n  --theme-dialogue-text-padding-right: 2.5rem;\n  --theme-dialogue-text-padding-bottom: 0.8rem;\n  --theme-dialogue-text-padding-left: 2.5rem;\n  --theme-dialogue-text-max-height: 6rem;\n\n  /* 名字框字号（关键变量：用户常想调整） */\n  --theme-dialogue-name-font-size: clamp(0.95rem, 1.4vw, 1.15rem);\n\n  /* 选项字号 */\n  --theme-choice-text-font-size: clamp(0.9rem, 1.4vw, 1.05rem);\n  --theme-choice-letter-font-size: clamp(0.85rem, 1.2vw, 1rem);\n\n  /* 面板 */\n  --theme-panel-bg: var(--vn-panel-bg);\n  --theme-panel-border: var(--vn-border);\n  --theme-panel-radius: 0px;\n\n  /* 按钮：padding 用 rem 不依赖字号 */\n  --theme-button-bg: rgba(42, 36, 32, 0.85);\n  --theme-button-border: rgba(139, 69, 19, 0.5);\n  --theme-button-radius: 0.1rem;\n  --theme-button-padding-y: 0.4rem;\n  --theme-button-padding-x: 0.75rem;\n\n  /* 弹幕：字号变量需带单位（之前裸数字是隐患） */\n  --theme-danmaku-top-offset: 10rem;\n  --theme-danmaku-bottom-offset: 7rem;\n  --theme-danmaku-horizontal-padding: 0.5rem;\n  --theme-danmaku-z-index: 5;\n  --theme-danmaku-font-size: 1.2rem;\n  --theme-danmaku-color: #ffffff;\n  --theme-danmaku-opacity: 0.9;\n\n  /* 舞台比例：横屏默认 16:9 */\n  --theme-aspect-ratio: 16 / 9;\n}\n\nhtml,\nbody {\n  margin: 0 !important;\n  padding: 0 !important;\n  background: var(--vn-bg);\n  color: var(--vn-fg);\n  font-family: 'Noto Serif SC', 'Noto Serif', Georgia, serif;\n}\n\n/* Global: hide all scrollbars */\n* {\n  scrollbar-width: none;\n}\n*::-webkit-scrollbar {\n  display: none;\n}\n\n.no-scrollbar::-webkit-scrollbar {\n  display: none;\n}\n.no-scrollbar {\n  -ms-overflow-style: none;\n  scrollbar-width: none;\n}\n\n/* Ink stain decoration */\n.ink-stain::before {\n  content: '';\n  position: absolute;\n  top: -10%;\n  right: -5%;\n  width: 40%;\n  height: 40%;\n  background: radial-gradient(ellipse at center, rgba(139, 69, 19, 0.15) 0%, transparent 70%);\n  pointer-events: none;\n  z-index: 0;\n}\n\n/* Column separator */\n.column-rule {\n  border-right: 1px solid var(--vn-border);\n  position: relative;\n}\n.column-rule::after {\n  content: '';\n  position: absolute;\n  top: 10%;\n  right: -1px;\n  width: 1px;\n  height: 80%;\n  background: linear-gradient(to bottom, transparent, var(--vn-muted) 20%, var(--vn-muted) 80%, transparent);\n  opacity: 0.3;\n}\n\n/* Headline rule */\n.headline-rule {\n  border-top: 2px solid var(--vn-fg);\n  border-bottom: 1px solid var(--vn-fg);\n  padding: 4px 0;\n  position: relative;\n  text-align: center;\n}\n.headline-rule::before {\n  content: '';\n  position: absolute;\n  top: 3px;\n  left: 0;\n  right: 0;\n  height: 1px;\n  background: var(--vn-fg);\n  opacity: 0.5;\n}\n\n/* Stamp / seal effect */\n.stamp-effect {\n  display: inline-block;\n  border: 2px solid var(--rust);\n  border-radius: 2px;\n  padding: 2px 8px;\n  transform: rotate(-2deg);\n  opacity: 0.8;\n  position: relative;\n}\n.stamp-effect::before {\n  content: '';\n  position: absolute;\n  inset: -1px;\n  border: 1px dashed var(--rust);\n  border-radius: 2px;\n  opacity: 0.4;\n}\n\n/* Toast clipping style */\n.toast-clipping {\n  background: var(--vn-toast-bg);\n  color: var(--vn-toast-text);\n  border: 1px solid var(--vn-border);\n  box-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);\n  transform: rotate(-0.5deg);\n  font-family: 'Noto Serif SC', Georgia, serif;\n}\n\n@keyframes toast-in {\n  0% {\n    opacity: 0;\n    transform: translateY(-20px) rotate(-0.5deg);\n  }\n  100% {\n    opacity: 1;\n    transform: translateY(0) rotate(-0.5deg);\n  }\n}\n@keyframes toast-out {\n  0% {\n    opacity: 1;\n    transform: translateY(0) rotate(-0.5deg);\n  }\n  100% {\n    opacity: 0;\n    transform: translateY(-20px) rotate(-0.5deg);\n  }\n}\n\n@keyframes fade-in-up {\n  from {\n    opacity: 0;\n    transform: translateY(8px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n.animate-fade-in-up {\n  animation: fade-in-up 0.4s ease-out forwards;\n}\n\n@keyframes cursor-blink {\n  0%,\n  50% {\n    opacity: 1;\n  }\n  51%,\n  100% {\n    opacity: 0;\n  }\n}\n\n/* === 2048 Grid === */\n.grid-2048 {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 6px;\n  background: rgba(90, 79, 64, 0.35);\n  border-radius: 4px;\n  padding: 6px;\n}\n.tile-2048 {\n  aspect-ratio: 1;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 900;\n  font-family: monospace;\n  border-radius: 3px;\n  transition: all 0.12s ease;\n  font-size: 1.1rem;\n}\n.tile-0 {\n  background: rgba(74, 64, 53, 0.25);\n}\n.tile-2 {\n  background: rgba(212, 197, 160, 0.2);\n  color: var(--vn-fg);\n}\n.tile-4 {\n  background: rgba(212, 197, 160, 0.3);\n  color: var(--vn-fg);\n}\n.tile-8 {\n  background: rgba(196, 162, 101, 0.4);\n  color: var(--vn-fg);\n}\n.tile-16 {\n  background: rgba(196, 162, 101, 0.55);\n  color: var(--vn-fg);\n}\n.tile-32 {\n  background: rgba(160, 82, 45, 0.4);\n  color: var(--paper-light);\n}\n.tile-64 {\n  background: rgba(160, 82, 45, 0.55);\n  color: var(--paper-light);\n}\n.tile-128 {\n  background: rgba(139, 69, 19, 0.5);\n  color: var(--paper-light);\n  font-size: 1rem;\n}\n.tile-256 {\n  background: rgba(139, 69, 19, 0.65);\n  color: var(--paper-light);\n  font-size: 1rem;\n}\n.tile-512 {\n  background: rgba(139, 69, 19, 0.8);\n  color: var(--paper-light);\n  font-size: 0.95rem;\n}\n.tile-1024 {\n  background: rgba(107, 52, 16, 0.8);\n  color: var(--paper-light);\n  font-size: 0.85rem;\n}\n.tile-2048 {\n  background: rgba(107, 52, 16, 0.95);\n  color: #ffd700;\n  font-size: 0.85rem;\n  text-shadow: 0 0 6px rgba(255, 215, 0, 0.4);\n}\n\n/* === Stock Chart === */\n.stock-chart-container {\n  position: relative;\n  height: 120px;\n  border: 1px solid rgba(90, 79, 64, 0.3);\n  background: rgba(42, 36, 32, 0.4);\n  border-radius: 2px;\n}\n\n/* === Provider status badges === */\n.provider-available {\n  color: var(--vn-success);\n}\n.provider-degraded {\n  color: var(--stain);\n}\n.provider-disabled {\n  color: var(--vn-muted);\n  opacity: 0.5;\n}\n\n/* === Module card === */\n.module-card {\n  border: 1px solid rgba(90, 79, 64, 0.4);\n  border-radius: 2px;\n  background: rgba(58, 51, 44, 0.3);\n  transition: all 0.2s;\n}\n.module-card:hover {\n  border-color: rgba(139, 69, 19, 0.4);\n  background: rgba(212, 197, 160, 0.05);\n}\n\n/* === Select option colors (for readability on system dropdowns) === */\nselect option {\n  background: #2d2620;\n  color: #d4c5a0;\n}\n\n/* === Input field === */\n.vn-input {\n  background: rgba(74, 64, 53, 0.3);\n  border: 1px solid rgba(90, 79, 64, 0.4);\n  color: var(--vn-fg);\n  padding: 6px 10px;\n  font-size: 0.8rem;\n  border-radius: 2px;\n  outline: none;\n  font-family: 'Noto Serif SC', serif;\n  width: 100%;\n}\n.vn-input:focus {\n  border-color: rgba(139, 69, 19, 0.5);\n}\n.vn-input::placeholder {\n  color: rgba(139, 125, 107, 0.5);\n}\n\n/* === Chat bubble === */\n.chat-bubble-user {\n  background: rgba(139, 69, 19, 0.2);\n  border: 1px solid rgba(139, 69, 19, 0.3);\n  border-radius: 2px 2px 2px 0;\n  padding: 8px 12px;\n  max-width: 80%;\n}\n.chat-bubble-ai {\n  background: rgba(58, 51, 44, 0.5);\n  border: 1px solid rgba(90, 79, 64, 0.3);\n  border-radius: 2px 2px 0 2px;\n  padding: 8px 12px;\n  max-width: 80%;\n}\n\n/* === Gold counter === */\n.gold-counter {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 3px 10px;\n  border: 1px solid rgba(196, 162, 101, 0.4);\n  background: rgba(196, 162, 101, 0.1)